from pathlib import Path
from bs4 import BeautifulSoup
import shutil
R=Path('/workspace/work/deliverables/dockside');C=R/'collection/dockside';V=R/'review'
def full(h):return '<div class="group" style="grid-column:1 / span 12;grid-row:1 / span 6">'+h+'</div>'
def save(n,h,intro='',title=None,late=False):
 p=V/f'reassembled/slide_{n:02}.html';b=BeautifulSoup(p.read_text(),'html.parser');b.select_one('.slide')['class']=['slide','overrides'];b.select_one('.head')['class']=['head']+(['overrides'] if late else [])
 if title:b.select_one('.title').clear();b.select_one('.title').append(BeautifulSoup(title,'html.parser'))
 body=b.select_one('.body');body.clear();body.append(BeautifulSoup(h,'html.parser'))
 if intro:body.append(BeautifulSoup('<div class="prose quiet" data-el="dockside-prose" style="grid-column:1 / span 12;grid-row:1 / span 6"><p>'+intro+'</p></div>','html.parser'))
 p.write_text(str(b))
def add(f,s):
 p=C/f'elements/{f}/element.css';p.write_text(p.read_text()+'\n'+s+'\n')
#08 insight columns.
