save(8,h,'데이터와 관찰을 바탕으로 시장 변화와 고객 니즈를 해석하고, 이를 통해<br>도출한 핵심 인사이트와 비즈니스 기회를 정리하는 페이지입니다.')
r='.card[data-el="dockside-card"]:has(.kick):has(.mark>.seat.icon)';s=f'''{r}{{position:absolute;left:47px;top:292px;width:315px;height:330px;display:block;padding:0;border:2px solid var(--page);border-radius:var(--radius);background:linear-gradient(140deg,color-mix(in srgb,var(--page) 50%,transparent),var(--n-2));box-shadow:0 10px 20px color-mix(in srgb,var(--ink) 7%,transparent);container-type:normal;flex:none}}{r}:nth-child(2){{left:394px}}{r}:nth-child(3){{left:741px}}{r}>.parts{{position:absolute;inset:0;padding:0;display:block}}{r} .kick{{position:absolute;left:-2px;top:-2px;width:315px;height:60px;display:flex;align-items:center;padding:0 var(--pad);font-size:var(--type-16);font-weight:var(--body-weight);color:var(--a1-on);background:var(--a1);border-radius:4px;box-shadow:0 7px 12px color-mix(in srgb,var(--a1) 25%,transparent)}}{r} .kick>.icon{{position:absolute;right:18px;top:12px;width:37px;height:37px;padding:9px;background:var(--ink);color:var(--page);border-radius:50%}}{r} .mark{{position:absolute;left:110px;top:55px;width:92px;height:92px;padding:0;background:none;border:0;box-shadow:none}}{r} .mark>.seat{{width:92px;height:92px;aspect-ratio:1;border:2px solid var(--page);border-radius:var(--radius);box-shadow:0 8px 14px color-mix(in srgb,var(--ink) 8%,transparent)}}{r} .name{{position:absolute;left:15px;top:164px;width:281px;font-size:var(--type-24);font-weight:var(--name-weight);text-align:center;color:var(--ink)}}{r} .note{{position:absolute;left:30px;top:216px;width:260px;font-size:var(--type-18);line-height:var(--body-line);color:var(--n-7)}}{r} .note::before{{content:"";position:absolute;left:-12px;right:-12px;top:-18px;height:1px;background:var(--n-3)}}''';add('card',s)
